INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-linear-algebra-set-08-s2-2', 'exam-linear-algebra-set-08', 'exam-linear-algebra-set-08-sec-2', 3, '求方程组的基础解系', '求方程组 $\\left\\{\\begin{aligned}x_{1}-8x_{2}+10x_{3}+2x_{4}&=0\\\\ 2x_{1}+4x_{2}+5x_{3}-x_{4}&=0\\end{aligned}\\right.$ 的基础解系； $3x_{1}+8x_{2}+6x_{3}-2x_{4}=0$', '[""]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 2, '[]'::jsonb, '长理线代期末试卷汇总-第08套', 2) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-linear-algebra-set-08-s2-3', 'exam-linear-algebra-set-08', 'exam-linear-algebra-set-08-sec-2', 3, '设，问取何值时，能由线性表示？', '设 $\\alpha_{1} = (1,3,0)^{T}, \\alpha_{2} = (1,2,1)^{T}, \\alpha_{3} = (1,1,2)^{T}, \\beta = (1,0,\\lambda)^{T}$ ，问 $\\lambda$ 取何值时， $\\beta$ 能由 $\\alpha_{1}, \\alpha_{2}, \\alpha_{3}$ 线性表示？并判断表达式是否惟一；', '[""]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 2, '[]'::jsonb, '长理线代期末试卷汇总-第08套', 3) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
