INSERT INTO public.exam_questions (id, exam_id, section_id, question_type, title, content, options, answer, answers, blanks, tolerance, unit, solution, hint, test_string, image, difficulty, tags, source, order_index) VALUES ('q-exam-linear-algebra-set-08-s3-0', 'exam-linear-algebra-set-08', 'exam-linear-algebra-set-08-sec-3', 4, '设阶可逆矩阵的一个特征值为,其', '设 $n$ 阶可逆矩阵 $A$ 的一个特征值为 $\\lambda$ , 其伴随矩阵为 $A^{*}$ , 求证: (1) $A^{-1}$ 的特征值为 $\\frac{1}{\\lambda}$ ; (2) $A^{*}$ 的特征值为 $\\frac{|A|}{\\lambda}$ 。', '[""]'::jsonb, '', '[]'::jsonb, NULL, NULL, NULL, '', NULL, NULL, NULL, 2, '[]'::jsonb, '长理线代期末试卷汇总-第08套', 0) ON CONFLICT (id) DO UPDATE SET exam_id = EXCLUDED.exam_id, section_id = EXCLUDED.section_id, question_type = EXCLUDED.question_type, title = EXCLUDED.title, content = EXCLUDED.content, options = EXCLUDED.options, answer = EXCLUDED.answer, answers = EXCLUDED.answers, blanks = EXCLUDED.blanks, tolerance = EXCLUDED.tolerance, unit = EXCLUDED.unit, solution = EXCLUDED.solution, hint = EXCLUDED.hint, test_string = EXCLUDED.test_string, image = EXCLUDED.image, difficulty = EXCLUDED.difficulty, tags = EXCLUDED.tags, source = EXCLUDED.source, order_index = EXCLUDED.order_index;
